<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';import { Download, Play, Plus, RefreshCw, Save, Trash2, Upload } from '@lucide/vue';import { api } from '../services/http';import SectionHeader from './SectionHeader.vue'
const simple=reactive<any>({enabled:true,schedule_time:'02:00',destination:'local',retention:3,endpoint:'',bucket:'',credentials:{}});const jobs=ref<any[]>([]);const selected=ref<any>(null);const editor=ref('');const importText=ref('');const status=ref('');const failed=ref(false);const createName=ref('');const credentialRef=ref('');const credentialJson=ref('{}');const verifyForm=reactive({archive_path:'',expected_sha256:'',key_env:''})
function note(t:string,e=false){status.value=t;failed.value=e;setTimeout(()=>status.value='',5000)}
async function load(){try{const [s,j]:any=await Promise.all([api('/api/v1/admin/backups/simple'),api('/api/v1/admin/backup-jobs')]);Object.assign(simple,s);jobs.value=j.jobs||[];if(selected.value){const updated=jobs.value.find(x=>x.id===selected.value.id);if(updated)select(updated)}}catch(e:any){note(e.message,true)}}
function select(job:any){selected.value=job;editor.value=JSON.stringify(job,null,2)}
async function saveSimple(){try{await api('/api/v1/admin/backups/simple',{method:'PUT',body:JSON.stringify(simple)});note('快捷灾备配置已保存');await load()}catch(e:any){note(e.message,true)}}
async function testSimple(){try{const d:any=await api('/api/v1/admin/backups/simple/test',{method:'POST',body:JSON.stringify(simple)});note(d.detail||'连接配置验证通过')}catch(e:any){note(e.message,true)}}
async function createJob(){try{const d:any=await api('/api/v1/admin/backup-jobs',{method:'POST',body:JSON.stringify({name:createName.value,source_id:'nightly-default'})});createName.value='';note('灾备任务已创建');await load();select(d.job)}catch(e:any){note(e.message,true)}}
async function saveJob(){try{const job=JSON.parse(editor.value);const d:any=await api(`/api/v1/admin/backup-jobs/${selected.value.id}`,{method:'PUT',body:JSON.stringify({job})});note('高级灾备任务已保存');await load();select(d.job)}catch(e:any){note(e.message,true)}}
async function validateJob(){try{const d:any=await api('/api/v1/admin/backup-jobs/validate',{method:'POST',body:JSON.stringify({job:JSON.parse(editor.value)})});note(d.valid===false?(d.errors||[]).join('；'):'任务验证通过',d.valid===false)}catch(e:any){note(e.message,true)}}
async function runJob(job:any){const phrase=`BACKUP ${job.id}`;if(prompt(`输入确认短语：${phrase}`)!==phrase)return;try{await api(`/api/v1/admin/backup-jobs/${job.id}/run`,{method:'POST',body:JSON.stringify({confirmation:phrase})});note('灾备任务执行完成');await load()}catch(e:any){note(e.message,true)}}
async function removeJob(job:any){if(!confirm(`确认删除 ${job.name}？`))return;try{await api(`/api/v1/admin/backup-jobs/${job.id}`,{method:'DELETE'});selected.value=null;editor.value='';note('任务已删除');await load()}catch(e:any){note(e.message,true)}}
async function exportJob(job:any){try{const d:any=await api(`/api/v1/admin/backup-jobs/${job.id}/export`);const b=new Blob([JSON.stringify(d,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`r20-backup-${job.id}.json`;a.click();URL.revokeObjectURL(a.href)}catch(e:any){note(e.message,true)}}
async function saveCredential(){try{await api('/api/v1/admin/backup-credentials',{method:'PUT',body:JSON.stringify({credential_ref:credentialRef.value,credentials:JSON.parse(credentialJson.value)})});credentialJson.value='{}';note('灾备凭证已加密保存')}catch(e:any){note(e.message,true)}}
async function verifyArchive(){try{const d:any=await api('/api/v1/admin/backup-jobs/verify',{method:'POST',body:JSON.stringify(verifyForm)});note(`归档校验通过：${d.members||0} 个文件`)}catch(e:any){note(e.message,true)}}
async function importJob(){try{const d:any=await api('/api/v1/admin/backup-jobs/import',{method:'POST',body:JSON.stringify({payload:JSON.parse(importText.value),name_override:''})});importText.value='';note('灾备任务已导入');await load();select(d.job)}catch(e:any){note(e.message,true)}}
onMounted(load)
</script>
<template><div class="space-y-4"><div v-if="status" class="panel border-l-4 p-3 text-xs" :class="failed?'text-loss':'text-profit'">{{status}}</div><section class="panel p-4 sm:p-5"><SectionHeader title="快捷灾备" subtitle="常用单目标定时备份"><template #actions><div class="flex gap-2"><button class="btn" @click="testSimple">测试连接</button><button class="btn btn-primary" @click="saveSimple"><Save :size="14"/>保存</button></div></template></SectionHeader><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><label class="subpanel p-3"><span class="label">启用</span><input v-model="simple.enabled" type="checkbox"/></label><div><label class="label">执行时间</label><input v-model="simple.schedule_time" class="input" type="time"/></div><div><label class="label">目标类型</label><select v-model="simple.destination" class="input"><option value="local">本地</option><option value="baidu">百度网盘 OAuth</option><option value="s3">S3 兼容</option><option value="oss">阿里云 OSS</option><option value="webdav">WebDAV</option></select></div><div><label class="label">保留份数</label><input v-model.number="simple.retention" class="input" type="number" min="1" max="30"/></div><div v-if="simple.destination!=='local'"><label class="label">Endpoint</label><input v-model="simple.endpoint" class="input"/></div><div v-if="['s3','oss'].includes(simple.destination)"><label class="label">Bucket</label><input v-model="simple.bucket" class="input"/></div></div></section><section class="panel p-4 sm:p-5"><SectionHeader title="高级灾备任务" subtitle="多目标、加密、校验、导入导出和手动执行" :count="jobs.length"><template #actions><button class="btn" @click="load"><RefreshCw :size="14"/></button></template></SectionHeader><div class="flex flex-col gap-2 sm:flex-row"><input v-model="createName" class="input" placeholder="新任务名称"/><button class="btn btn-primary shrink-0" @click="createJob"><Plus :size="14"/>创建任务</button></div><div class="mt-4 grid gap-2.5 lg:grid-cols-2"><article v-for="job in jobs" :key="job.id" class="subpanel key-card p-4" :class="job.enabled?'key-card-profit':'key-card-warning'"><div class="flex justify-between gap-2"><button class="text-left" @click="select(job)"><b>{{job.name}}</b><p class="mt-1 text-[9px] font-mono muted">{{job.id}}</p></button><span class="badge" :class="job.enabled?'badge-profit':'badge-warning'">{{job.enabled?'启用':'停用'}}</span></div><p class="mt-2 text-[10px] muted">{{(job.schedule_times||[]).join('、')}} · {{(job.targets||[]).length}} 个目标</p><div class="mt-3 flex flex-wrap gap-2"><button class="btn !min-h-8 !py-1" @click="select(job)">编辑</button><button class="btn !min-h-8 !py-1" @click="runJob(job)"><Play :size="12"/>执行</button><button class="btn !min-h-8 !py-1" @click="exportJob(job)"><Download :size="12"/>导出</button><button class="btn btn-danger !min-h-8 !py-1" @click="removeJob(job)"><Trash2 :size="12"/></button></div></article></div></section><section v-if="selected" class="panel p-4 sm:p-5"><SectionHeader :title="`编辑：${selected.name}`" subtitle="JSON 高级编辑器保留全部目标和加密参数"><template #actions><div class="flex gap-2"><button class="btn" @click="validateJob">验证</button><button class="btn btn-primary" @click="saveJob"><Save :size="14"/>保存任务</button></div></template></SectionHeader><textarea v-model="editor" class="input min-h-[420px] font-mono text-[11px] leading-6"></textarea></section><div class="grid gap-4 xl:grid-cols-2"><section class="panel p-4"><SectionHeader title="导入灾备任务"/><textarea v-model="importText" class="input min-h-32 font-mono text-xs" placeholder="粘贴导出的任务 JSON"></textarea><button class="btn mt-3" @click="importJob"><Upload :size="14"/>导入</button></section><section class="panel p-4"><SectionHeader title="加密凭证存储" subtitle="S3、OSS、WebDAV、百度 OAuth 等目标凭证"/><label class="label">Credential Ref</label><input v-model="credentialRef" class="input" placeholder="例如 oss-prod"/><label class="label mt-3">凭证 JSON</label><textarea v-model="credentialJson" class="input min-h-28 font-mono text-xs" placeholder='{"access_key_id":"...","secret_access_key":"..."}'></textarea><button class="btn btn-primary mt-3" @click="saveCredential"><Save :size="14"/>加密保存</button></section></div><section class="panel p-4"><SectionHeader title="归档完整性校验" subtitle="仅允许校验项目 backups/ 目录内归档"/><div class="grid gap-3 lg:grid-cols-3"><div><label class="label">归档路径</label><input v-model="verifyForm.archive_path" class="input" placeholder="backups/example.tar.gz.enc"/></div><div><label class="label">期望 SHA-256（可选）</label><input v-model="verifyForm.expected_sha256" class="input"/></div><div><label class="label">解密密钥环境变量（可选）</label><input v-model="verifyForm.key_env" class="input" placeholder="R20_BACKUP_ENCRYPTION_KEY"/></div></div><button class="btn mt-3" @click="verifyArchive">验证归档</button></section></div></template>
